def _clean_dataframe(df: pd.DataFrame, decimals: int = NUMERIC_DECIMALS) -> pd.DataFrame:
    """Round float columns and replace pandas NaN/NaT with None for clean JSON.

    Mutating display values is acceptable here because float aggregation noise
    is not real signal — Olist currency data has at most 2 decimals to begin
    with. Rounding to 3 keeps headroom for derived ratios and averages.
    """
    if df.empty:
        return df

    df = df.copy()
    float_cols = df.select_dtypes(include=["float", "float64", "float32"]).columns
    if len(float_cols):
        df[float_cols] = df[float_cols].round(decimals)
    # JSON has no NaN/NaT — convert to None so downstream serialization works.
    return df.where(df.notnull(), None)


def _fmt_cell(value: Any) -> str:
    """Human-friendly cell format used in the answer string.

    - Integers: thousand-separated, no decimals
    - Floats:   thousand-separated, up to NUMERIC_DECIMALS decimals, trailing zeros stripped
    - None/NaN: empty string
    - Other:    str()
    """
    if value is None:
        return ""
    if isinstance(value, bool):
        return str(value)
    if isinstance(value, int):
        return f"{value:,}"
    if isinstance(value, float):
        if math.isnan(value):
            return ""
        rounded = round(value, NUMERIC_DECIMALS)
        if rounded == int(rounded):
            return f"{int(rounded):,}"
        s = f"{rounded:,.{NUMERIC_DECIMALS}f}".rstrip("0").rstrip(".")
        return s
    return str(value)


