            self._client.table("sessions")
            .select("*")
            .eq("id", session_id)
            .execute()
        )
        if not res.data:
            return None
        row = res.data[0]

        # Fetch query memories ordered by position
        mem_res = (
            self._client.table("query_memories")
            .select("*")
            .eq("session_id", session_id)
            .order("position")
            .execute()
        )
        queries = [
            QueryMemory(
                question=m["question"],
